/**
 * REQ-CONN-007 / REQ-ID-001: the engine runs exactly while an identity exists. Observing the
 * identity starts it on startup-with-identity and after login, and stops it on logout.
 */
fun bindEngineToIdentity(scope: CoroutineScope, identity: Flow<String?>, sync: SyncController): Job =
    scope.launch {
        identity.distinctUntilChanged().collect { me ->
            if (me == null) sync.stop() else sync.start(me)
